"""Background client for AgentPulse v2 REST + WebSocket API.

Reads config from ~/.claude/agentpulse/config.json, bootstraps today's
session state via GET /api/v2/sessions?since=<midnight>, then streams
updates via /ws/v2. Runs entirely in a daemon thread with its own
asyncio event loop.
"""

from __future__ import annotations

import asyncio
import json
import logging
import threading
import tkinter as tk
import urllib.request
from collections.abc import Callable
from datetime import datetime, timedelta
from typing import Any

from personal_assistant_dashboard.agentpulse_config import (
    HTTP_TIMEOUT_S,
    load_agentpulse_config,
)

logger = logging.getLogger(__name__)

_BACKOFF_CAP = 30.0
_INITIAL_BACKOFF = 1.0


def _today_local_date() -> str:
    """Return today's date as YYYY-MM-DD in local time.

    Single source of "today" — used by the cost-by-day lookup and the
    day-boundary scheduler so both agree on the bucket boundary.
    """
    return datetime.now().strftime("%Y-%m-%d")


def _session_response_to_row(resp: dict[str, Any]) -> dict[str, Any]:
    """Convert a v2 SessionResponse to an InfoTab row dict.

    All timestamps are seconds (v2 normalized). today_cost_usd seeded
    from cost_by_day; replaced live by session_today_cost_usd from
    statusline_logged frames. is_active is derived (v2 doesn't return
    it directly).
    """
    cost_by_day = resp.get("cost_by_day") or {}
    today_cost = float(cost_by_day.get(_today_local_date(), 0.0))
    last_event = resp.get("last_event")
    ended_at = resp.get("ended_at")
    is_active = ended_at is None and last_event != "SessionEnd"
    return {
        "session_id": resp.get("session_id", ""),
        "process_id": resp.get("process_id", ""),
        "pid": resp.get("pid") or 0,
        "source_system": resp.get("source_system") or "",
        "cwd": resp.get("cwd", ""),
        "model_display_name": resp.get("model_name") or "",
        "today_cost_usd": today_cost,
        "session_total_cost_usd": float(resp.get("total_cost_usd") or 0.0),
        "total_input_tokens": resp.get("total_input_tokens") or 0,
        "total_output_tokens": resp.get("total_output_tokens") or 0,
        "context_used_pct": int(resp.get("context_used_pct") or 0),
        "lines_added": resp.get("lines_added") or 0,
        "lines_removed": resp.get("lines_removed") or 0,
        "started_at": float(resp.get("started_at") or 0.0),
        "last_activity_at": float(resp.get("last_activity_at") or 0.0),
        "ended_at": ended_at,
        "last_event": last_event,
        "last_event_at": float(resp.get("last_event_at") or 0.0),
        "derived_state": resp.get("derived_state"),
        "is_active": is_active,
    }


def _next_backoff(current: float) -> float:
    """Compute next exponential backoff delay, capped at _BACKOFF_CAP."""
    return min(current * 2, _BACKOFF_CAP)


class AgentPulseClient:
    """Background client that streams AgentPulse session data.

    Call ``start()`` to launch the daemon thread and ``stop()`` to shut
    it down. The ``on_update`` callback is scheduled on the Tkinter main
    thread whenever session data changes.
    """

    def __init__(self, root: tk.Tk, on_update: Callable[[], None]) -> None:
        self._root = root
        self._on_update = on_update
        self._sessions: dict[str, dict[str, Any]] = {}
        self._limits: dict[str, Any] = {}
        self._lock = threading.Lock()
        self._stop_event = threading.Event()
        self._loop: asyncio.AbstractEventLoop | None = None

        config = load_agentpulse_config()
        if config is None:
            self._host: str | None = None
            self._port: int | None = None
            self.fetch_limits_enabled: bool = False
        else:
            self._host = config.host
            self._port = config.port
            self.fetch_limits_enabled = config.fetch_limits

    def start(self) -> None:
        """Launch the background connection thread and schedule day-boundary refresh."""
        if self._host is None:
            logger.info("AgentPulse config not found; client disabled")
            return
        self._schedule_day_boundary_refresh()
        t = threading.Thread(target=self._run, daemon=True, name="agentpulse")
        t.start()

    def stop(self) -> None:
        """Signal the background thread to shut down."""
        self._stop_event.set()
        if self._loop is not None:
            self._loop.call_soon_threadsafe(self._loop.stop)

    def get_sessions(self) -> list[dict[str, Any]]:
        """Return a snapshot of current sessions."""
        with self._lock:
            return list(self._sessions.values())

    def get_limits(self) -> dict[str, Any]:
        """Return the most recent limits snapshot."""
        with self._lock:
            return dict(self._limits)

    def refresh(self) -> None:
        """Force a REST re-fetch of sessions and limits."""
        if self._host is None:
            return
        threading.Thread(
            target=self._rest_fetch_all, daemon=True, name="agentpulse-refresh"
        ).start()

    def _schedule_day_boundary_refresh(self) -> None:
        """Schedule a refresh callback for the next local midnight."""
        now = datetime.now()
        midnight = (now + timedelta(days=1)).replace(
            hour=0, minute=0, second=0, microsecond=0
        )
        ms_until = max(1, int((midnight - now).total_seconds() * 1000))
        try:
            self._root.after(ms_until, self._on_day_boundary)
        except (RuntimeError, tk.TclError):
            pass  # Tk destroyed

    def _on_day_boundary(self) -> None:
        """Day-boundary callback: refresh and reschedule."""
        self.refresh()
        self._schedule_day_boundary_refresh()

    def _rest_fetch_all(self) -> None:
        """Fetch sessions, statuslines, and limits (when enabled).

        Used by the refresh button.
        """
        self._rest_fetch()
        self._rest_fetch_statuslines()
        if self.fetch_limits_enabled:
            self._rest_fetch_limits()

    def _run(self) -> None:  # pragma: no cover - asyncio thread entry
        """Background thread entry point."""
        self._loop = asyncio.new_event_loop()
        asyncio.set_event_loop(self._loop)
        try:
            self._loop.run_until_complete(self._connect_loop())
        except Exception:
            logger.exception("AgentPulse client crashed")
        finally:
            self._loop.close()

    async def _connect_loop(self) -> None:  # pragma: no cover - WS I/O loop
        """Bootstrap via REST, then maintain a /ws/v2 connection.

        Per v2 client guidance: open WS, run REST bootstrap, process
        live frames. On disconnect: clear state, notify UI, exponential
        backoff, re-bootstrap.
        """
        import websockets

        backoff = _INITIAL_BACKOFF
        while not self._stop_event.is_set():
            uri = f"ws://{self._host}:{self._port}/ws/v2"
            try:
                async with websockets.connect(uri, ping_interval=None) as ws:
                    logger.debug("WS connected to %s", uri)

                    self._rest_fetch()
                    self._rest_fetch_statuslines()
                    if self.fetch_limits_enabled:
                        self._rest_fetch_limits()
                    self._notify_ui()
                    backoff = _INITIAL_BACKOFF

                    async for raw in ws:
                        if self._stop_event.is_set():
                            break
                        try:
                            msg = json.loads(raw)
                        except json.JSONDecodeError:
                            continue
                        logger.debug(
                            "WS recv type=%s sid=%s",
                            msg.get("type", "?"),
                            (msg.get("session_id") or "?")[:8],
                        )
                        self._handle_ws_message(msg)
            except Exception:
                logger.debug("AgentPulse WS disconnected, retrying in %.0fs", backoff)

            with self._lock:
                self._sessions.clear()
                self._limits.clear()
            self._notify_ui()
            if self._stop_event.is_set():
                break
            await asyncio.sleep(backoff)
            backoff = _next_backoff(backoff)

    def _rest_fetch(self) -> None:
        """Bootstrap fetch: GET /api/v2/sessions?since=<midnight>.

        Returns all sessions touched today (active or ended). Replaces
        in-memory state. On HTTP failure, leaves state unchanged so the
        UI doesn't flicker to empty during transient network issues.
        """
        midnight = (
            datetime.now()
            .replace(hour=0, minute=0, second=0, microsecond=0)
            .timestamp()
        )
        url = f"http://{self._host}:{self._port}" f"/api/v2/sessions?since={midnight}"
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT_S) as resp:
                data = json.loads(resp.read())
        except Exception:
            logger.debug("AgentPulse REST sessions fetch failed")
            return
        if not isinstance(data, list):
            return
        merged = {
            s["session_id"]: _session_response_to_row(s)
            for s in data
            if isinstance(s, dict) and "session_id" in s
        }
        with self._lock:
            self._sessions = merged
        self._notify_ui()

    def _rest_fetch_statuslines(self) -> None:
        """Seed token/line counters from today's statuslines log.

        v2's SessionResponse carries cost and context but not tokens or
        lines — those only ride on statusline rows. After bootstrapping
        sessions, pull today's statuslines (descending) and apply the
        latest one per session_id.

        Known limitation: the log endpoint caps ``limit`` at 1000, so
        on busy days only the most-active sessions are seeded here;
        less-active sessions stay at zero until their next live frame.
        Cross-process / per-day aggregation for tokens and lines is a
        v2 API gap to address upstream.
        """
        midnight = (
            datetime.now()
            .replace(hour=0, minute=0, second=0, microsecond=0)
            .timestamp()
        )
        url = (
            f"http://{self._host}:{self._port}"
            f"/api/v2/log/statuslines?since={midnight}&order=desc&limit=1000"
        )
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT_S) as resp:
                data = json.loads(resp.read())
        except Exception:
            logger.debug("AgentPulse statuslines fetch failed")
            return
        if not isinstance(data, list):
            return
        seen: set[str] = set()
        with self._lock:
            for row in data:
                if not isinstance(row, dict):
                    continue
                sid = row.get("session_id")
                if not sid or sid in seen:
                    continue
                target = self._sessions.get(sid)
                if target is None:
                    continue
                self._apply_statusline_fields(target, row)
                seen.add(sid)
        self._notify_ui()

    def _fetch_session_one(self, session_id: str) -> None:
        """Fetch one session by id and insert it into the in-memory map.

        Called from the hook_logged handler when a session_id appears
        that we haven't bootstrapped. Fire-and-forget on failure — the
        next hook for the same session will retry.
        """
        url = f"http://{self._host}:{self._port}" f"/api/v2/sessions/{session_id}"
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT_S) as resp:
                data = json.loads(resp.read())
        except Exception:
            logger.debug("AgentPulse fetch session %s failed", session_id[:8])
            return
        if not isinstance(data, dict) or "session_id" not in data:
            return
        row = _session_response_to_row(data)
        with self._lock:
            self._sessions[session_id] = row

    def _rest_fetch_limits(self) -> None:
        """Fetch most-recent limits row via /api/v2/log/api-limits.

        Uses the log endpoint with ``order=desc&limit=1`` to get the
        latest snapshot directly. The row shape matches the
        api_limits_logged WS frame, so we apply the same handler logic.
        """
        url = (
            f"http://{self._host}:{self._port}"
            f"/api/v2/log/api-limits?order=desc&limit=1"
        )
        try:
            with urllib.request.urlopen(url, timeout=HTTP_TIMEOUT_S) as resp:
                data = json.loads(resp.read())
        except Exception:
            logger.debug("AgentPulse limits fetch failed")
            return
        if not isinstance(data, list) or not data:
            return
        row = data[0]
        if not isinstance(row, dict):
            return
        self._handle_api_limits_logged(row)
        self._notify_ui()

    def _handle_ws_message(self, msg: dict[str, Any]) -> None:
        """Dispatch a v2 WebSocket frame and update in-memory state."""
        msg_type = msg.get("type", "")

        if msg_type == "hook_logged":
            self._handle_hook_logged(msg)
        elif msg_type == "statusline_logged":
            self._handle_statusline_logged(msg)
        elif msg_type == "pid_death_logged":
            self._handle_pid_death_logged(msg)
        elif msg_type == "api_limits_logged":
            self._handle_api_limits_logged(msg)
        # else: unknown type — tolerate per v2 client guidance

        self._notify_ui()

    def _handle_hook_logged(self, msg: dict[str, Any]) -> None:
        session_id = msg.get("session_id", "")
        if not session_id:
            return
        with self._lock:
            row = self._sessions.get(session_id)

        if row is None:
            self._fetch_session_one(session_id)
            return

        event_name = msg.get("event_name", "")
        received_at = float(msg.get("received_at") or 0.0)

        with self._lock:
            row["last_event"] = event_name
            row["last_event_at"] = received_at
            row["derived_state"] = msg.get("derived_state")
            if event_name == "SessionEnd":
                row["ended_at"] = received_at
                row["is_active"] = False

    _STATUSLINE_FIELD_MAP: tuple[tuple[str, str, type], ...] = (
        ("session_today_cost_usd", "today_cost_usd", float),
        ("session_total_cost_usd", "session_total_cost_usd", float),
        ("context_used_pct", "context_used_pct", int),
        ("model_name", "model_display_name", str),
        ("total_input_tokens", "total_input_tokens", int),
        ("total_output_tokens", "total_output_tokens", int),
        ("lines_added", "lines_added", int),
        ("lines_removed", "lines_removed", int),
    )

    def _apply_statusline_fields(
        self, row: dict[str, Any], msg: dict[str, Any]
    ) -> None:
        """Copy statusline fields from a frame/log row into an existing session row."""
        for src, dst, cast in self._STATUSLINE_FIELD_MAP:
            val = msg.get(src)
            if val is not None:
                row[dst] = cast(val)

    def _handle_statusline_logged(self, msg: dict[str, Any]) -> None:
        session_id = msg.get("session_id", "")
        if not session_id:
            return
        with self._lock:
            row = self._sessions.get(session_id)
            if row is None:
                # Statusline arrived before any hook — create pending row.
                row = {
                    "session_id": session_id,
                    "process_id": msg.get("process_id", ""),
                    "pid": msg.get("pid") or 0,
                    "source_system": msg.get("source_system") or "",
                    "cwd": msg.get("cwd", ""),
                    "model_display_name": "",
                    "today_cost_usd": 0.0,
                    "session_total_cost_usd": 0.0,
                    "total_input_tokens": 0,
                    "total_output_tokens": 0,
                    "context_used_pct": 0,
                    "lines_added": 0,
                    "lines_removed": 0,
                    "started_at": float(msg.get("received_at") or 0.0),
                    "last_activity_at": float(msg.get("received_at") or 0.0),
                    "ended_at": None,
                    "last_event": None,
                    "last_event_at": 0.0,
                    "derived_state": None,
                    "is_active": True,
                }
                self._sessions[session_id] = row
            self._apply_statusline_fields(row, msg)

    def _handle_pid_death_logged(self, msg: dict[str, Any]) -> None:
        process_id = msg.get("process_id", "")
        source_system = msg.get("source_system", "")
        observed_at = float(msg.get("observed_at") or 0.0)
        if not process_id:
            return
        with self._lock:
            for row in self._sessions.values():
                if (
                    row.get("process_id") == process_id
                    and row.get("source_system") == source_system
                ):
                    row["ended_at"] = observed_at
                    row["is_active"] = False

    def _handle_api_limits_logged(self, msg: dict[str, Any]) -> None:
        with self._lock:
            self._limits = {
                "five_hour": {
                    "utilization": msg.get("five_hour_utilization"),
                    "resets_at": msg.get("five_hour_resets_at"),
                },
                "seven_day": {
                    "utilization": msg.get("seven_day_utilization"),
                    "resets_at": msg.get("seven_day_resets_at"),
                },
            }

    def _notify_ui(self) -> None:
        """Schedule the update callback on the Tkinter main thread."""
        try:
            self._root.after(0, self._on_update)
        except (RuntimeError, tk.TclError):
            pass  # Tk destroyed
